export function isMobileViewport(){return (typeof matchMedia==='function'&&matchMedia('(pointer: coarse)').matches)||/Android|iPhone|iPad/i.test(navigator.userAgent||'');}
export function viewportLayout(width,height,mobile){const rotated=Boolean(mobile&&height>width);return {width:rotated?height:width,height:rotated?width:height,rotated,mobile};}
export function pointerIn(element,event){const r=element.getBoundingClientRect();if(document.body.classList.contains('landscape-rotated'))return {x:event.clientY-r.top,y:r.right-event.clientX};return {x:event.clientX-r.left,y:event.clientY-r.top};}
export function installLandscapeLayout(){const shell=document.querySelector('#app-shell');if(!shell)return;let frame;
 function update(){const size=viewportLayout(window.innerWidth,window.innerHeight,isMobileViewport());document.body.classList.toggle('landscape-rotated',size.rotated);document.body.classList.toggle('mobile-landscape',size.mobile);shell.style.setProperty('--ui-w',size.width+'px');shell.style.setProperty('--ui-h',size.height+'px');shell.style.width=size.width+'px';shell.style.height=size.height+'px';shell.dataset.rotated=String(size.rotated);window.dispatchEvent(new Event('musiclayoutchange'));}
 function resize(){cancelAnimationFrame(frame);frame=requestAnimationFrame(update);}window.addEventListener('resize',resize);window.addEventListener('orientationchange',resize);window.visualViewport?.addEventListener('resize',resize);update();return update;}
export async function lockLandscape(){if(!isMobileViewport())return false;try{if(screen.orientation?.lock){await screen.orientation.lock('landscape');return true;}}catch{}return false;}
